android.extraProguardRules:
# Detox runs its test APK against the minified release app, which must keep the Kotlin runtime it relies on
-keep class kotlin.** { *; }
-keep class kotlinx.coroutines.** { *; }
# Glide (react-native-fast-image, bench only) instantiates its modules by reflection
-keep public class * implements com.bumptech.glide.module.GlideModule { <init>(...); }
-keep class * extends com.bumptech.glide.module.AppGlideModule { <init>(...); }
